contracts/OracleRandomNumber.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title OracleRandomNumber
 * @dev A contract that facilitates the generation of verifiable random numbers
 * through an oracle service. The contract stores, manages, and verifies requests
 * for random numbers with cryptographic verification.
 */
contract OracleRandomNumber {
    // Events
    /**
     * @dev Emitted when a random number is requested
     * @param requestId The unique identifier for the request
     * @param requester The address that initiated the request
     */
    event RandomNumberRequested(uint256 indexed requestId, address indexed requester);
    
    /**
     * @dev Emitted when a random number request is fulfilled
     * @param requestId The unique identifier for the fulfilled request
     * @param randomNumber The generated random number
     * @param requester The address that initiated the request
     */
    event RandomNumberFulfilled(uint256 indexed requestId, uint256 randomNumber, address indexed requester);

    /// @notice Address of the oracle service authorized to fulfill random number requests
    address public oracle;
    
    /// @notice Address of the contract owner
    address owner;
    
    /// @notice Counter for request IDs
    uint256 public nextRequestId;

    /**
     * @dev Structure to store random number requests
     * @param requester The address requesting the random number
     * @param fulfilled Boolean indicating if the request has been fulfilled
     * @param randomNumber The generated random number (zero if unfulfilled)
     */
    struct RandomRequest {
        address requester;
        bool fulfilled;
        uint256 randomNumber;
    }

    /// @notice Mapping from request ID to request details
    mapping(uint256 => RandomRequest) public requests;

    /**
     * @dev Restricts function access to the contract owner
     */
    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action");
        _;
    }

    /**
     * @dev Initializes the contract with the oracle address
     * @param _oracle Address of the authorized oracle service
     */
    constructor(address _oracle) {
        oracle = _oracle;
        nextRequestId = 1;
        owner = msg.sender;
    }

    /**
     * @dev Allows any address to request a random number
     * @return requestId The unique identifier for the random number request
     */
    function requestRandomNumber() public returns (uint256) {
        uint256 requestId = nextRequestId++;
        requests[requestId] = RandomRequest({
            requester: msg.sender, // Store the requester address (could be an EOA or another contract)
            fulfilled: false,
            randomNumber: 0
        });

        emit RandomNumberRequested(requestId, msg.sender);
        return requestId;
    }

    /**
     * @dev Fulfills a random number request with cryptographic verification
     * @param _requestId The ID of the request to fulfill
     * @param _randomNumber The random number provided by the oracle
     * @param _signature The oracle's cryptographic signature of the random number
     */
    function fulfillRandomNumber(uint256 _requestId, uint256 _randomNumber, bytes memory _signature) public {
        require(msg.sender == oracle, "Only the oracle can fulfill the request");
        require(!requests[_requestId].fulfilled, "Request already fulfilled");
        require(verifySignature(_requestId, _randomNumber, _signature), "Invalid signature");

        RandomRequest storage request = requests[_requestId];
        request.fulfilled = true;
        request.randomNumber = _randomNumber;

        // Notify the requester (which could be a contract like TestOracleRandomNumber) with the fulfilled random number
        if (isContract(request.requester)) {
            // Call the fulfillRandomNumber function on the requester contract
            (bool success, ) = request.requester.call(
                abi.encodeWithSignature("fulfillRandomNumber(uint256)", _randomNumber)
            );
            require(success, "Callback to the requester contract failed");
        }

        emit RandomNumberFulfilled(_requestId, _randomNumber, request.requester);
    }

    /**
     * @dev Verifies the oracle's signature for a random number
     * @param _requestId The ID of the request being fulfilled
     * @param _randomNumber The random number to verify
     * @param _signature The cryptographic signature to verify
     * @return True if the signature is valid, false otherwise
     */
    function verifySignature(uint256 _requestId, uint256 _randomNumber, bytes memory _signature) internal view returns (bool) {
        bytes32 messageHash = keccak256(abi.encodePacked(_requestId, _randomNumber));
        bytes32 ethSignedMessageHash = getEthSignedMessageHash(messageHash);
        return recoverSigner(ethSignedMessageHash, _signature) == oracle;
    }

    /**
     * @dev Checks if an address is a contract
     * @param account The address to check
     * @return True if the address contains contract code, false otherwise
     */
    function isContract(address account) internal view returns (bool) {
        uint32 size;
        assembly {
            size := extcodesize(account)
        }
        return size > 0;
    }

    /**
     * @dev Creates the Ethereum signed message hash following EIP-191
     * @param _messageHash The original message hash
     * @return The Ethereum signed message hash
     */
    function getEthSignedMessageHash(bytes32 _messageHash) public pure returns (bytes32) {
        return keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", _messageHash));
    }

    /**
     * @dev Recovers the address that signed a message
     * @param _ethSignedMessageHash The Ethereum signed message hash
     * @param _signature The signature to verify
     * @return The address that created the signature
     */
    function recoverSigner(bytes32 _ethSignedMessageHash, bytes memory _signature) public pure returns (address) {
        (bytes32 r, bytes32 s, uint8 v) = splitSignature(_signature);
        return ecrecover(_ethSignedMessageHash, v, r, s);
    }

    /**
     * @dev Splits a signature into its r, s, v components
     * @param _signature The signature to split
     * @return r The r component of the signature
     * @return s The s component of the signature
     * @return v The v component of the signature
     */
    function splitSignature(bytes memory _signature) public pure returns (bytes32 r, bytes32 s, uint8 v) {
        require(_signature.length == 65, "Invalid signature length");

        assembly {
            r := mload(add(_signature, 32))
            s := mload(add(_signature, 64))
            v := byte(0, mload(add(_signature, 96)))
        }
    }

    /**
     * @dev Updates the address of the oracle service
     * @param newOracle The address of the new oracle service
     */
    function changeOracle(address newOracle) public onlyOwner {
        oracle = newOracle;
    }

    /**
     * @dev Retrieves the random number for a specific request
     * @param _requestId The ID of the request
     * @return The random number and whether the request has been fulfilled
     */
    function getRandomNumber(uint256 _requestId) public view returns (uint256, bool) {
        RandomRequest storage request = requests[_requestId];
        return (request.randomNumber, request.fulfilled);
    }
}

contracts/RandomeNumberConsumer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @dev Interface for interacting with the OracleRandomNumber contract
 * Defines the functions required to request and retrieve random numbers
 */
interface IOracleRandomNumber {
    function requestRandomNumber() external returns (uint256);
    function getRandomNumber(uint256 _requestId) external view returns (uint256, bool);
    function nextRequestId() external view returns (uint256);
}

/**
 * @title RandomNumberConsumer
 * @dev A contract that consumes verifiable random numbers from the OracleRandomNumber contract
 * It requests random numbers and processes the callback containing the result
 */
contract RandomNumberConsumer {
    /// @notice Address of the contract owner
    address public owner;
    
    /// @notice Address of the oracle providing random numbers
    address public oracleAddress;
    
    /// @notice Interface to interact with the oracle contract
    IOracleRandomNumber public oracleContract;
    
    /// @notice Maps request IDs to their fulfilled random number values
    mapping(uint256 => uint256) public randomNumbers;
    
    /// @notice Tracks whether a request ID has been fulfilled
    mapping(uint256 => bool) public fulfilled;
    
    /**
     * @dev Emitted when a random number is requested from the oracle
     * @param requestId The unique identifier for the request
     */
    event RandomNumberRequested(uint256 indexed requestId);
    
    /**
     * @dev Emitted when a random number is received from the oracle
     * @param requestId The unique identifier for the fulfilled request
     * @param randomValue The random number value received
     */
    event RandomNumberReceived(uint256 indexed requestId, uint256 randomValue);

    /**
     * @dev Restricts function access to the contract owner
     */
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    /**
     * @dev Initializes the contract with the oracle address
     * @param _oracleAddress Address of the random number oracle
     */
    constructor(address _oracleAddress) {
        owner = msg.sender;
        oracleAddress = _oracleAddress;
        oracleContract = IOracleRandomNumber(_oracleAddress);
    }

    /**
     * @dev Requests a random number from the oracle
     * @return requestId The unique identifier for the random number request
     */
    function requestRandom() public returns (uint256) {
        uint256 requestId = oracleContract.requestRandomNumber();
        emit RandomNumberRequested(requestId);
        return requestId;
    }

    /**
     * @dev Callback function that the oracle calls when the random number is ready
     * @param _randomNumber The generated random number
     * Note: In production, the oracle would typically provide both the requestId and random number
     */
    function fulfillRandomNumber(uint256 _randomNumber) external {
        // Make sure only the oracle contract can call this function
        require(msg.sender == oracleAddress, "Only oracle can fulfill");
        
        // In a real implementation, you would need to associate this random number
        // with the correct requestId. For simplicity, we're just storing the latest.
        uint256 lastRequestId = getLatestRequestId();
        randomNumbers[lastRequestId] = _randomNumber;
        fulfilled[lastRequestId] = true;
        
        emit RandomNumberReceived(lastRequestId, _randomNumber);
    }
    
    /**
     * @dev Helper function to get the latest request ID
     * @return The most recent request ID based on the oracle's counter
     * Note: In a production implementation, you'd likely track the requestIds explicitly
     */
    function getLatestRequestId() internal view returns (uint256) {
        return oracleContract.nextRequestId() - 1;
    }
    
    /**
     * @dev Retrieves a random number if it's been fulfilled
     * @param _requestId The ID of the request
     * @return The random number and whether the request has been fulfilled
     */
    function getRandomNumber(uint256 _requestId) public view returns (uint256, bool) {
        return (randomNumbers[_requestId], fulfilled[_requestId]);
    }
    
    /**
     * @dev Updates the oracle address if needed
     * @param _newOracleAddress The address of the new oracle
     */
    function setOracleAddress(address _newOracleAddress) public onlyOwner {
        oracleAddress = _newOracleAddress;
        oracleContract = IOracleRandomNumber(_newOracleAddress);
    }
    
    /**
     * @dev Example utility function demonstrating random number usage
     * @param _requestId The ID of the fulfilled random number request
     * @param _modulus The modulo to apply to the random number
     * @return The random number modulo _modulus (creates a bounded result)
     */
    function getRandomModulo(uint256 _requestId, uint256 _modulus) public view returns (uint256) {
        require(fulfilled[_requestId], "Random number not yet fulfilled");
        return randomNumbers[_requestId] % _modulus;
    }
}

contracts/TestOracleRandomNumber.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./OracleRandomNumber.sol";  // Make sure to import the OracleRandomNumber contract

contract TestOracleRandomNumber {
    OracleRandomNumber public oracleContract;
    bool public randomNumberReceived;
    uint256 public receivedRandomNumber;

    // Event for logging the random number received
    event RandomNumberLogged(uint256 randomNumber);

    constructor(address _oracleContractAddress) {
        // Set the address of the deployed OracleRandomNumber contract
        oracleContract = OracleRandomNumber(_oracleContractAddress);
    }

    // Function to request a random number from the OracleRandomNumber contract
    function requestRandomNumber() public {
        oracleContract.requestRandomNumber();
    }

    // This function should be called by the oracle after fulfilling the random number
    function fulfillRandomNumber(uint256 _randomNumber) public {
        // Only allow the oracle contract to fulfill the random number
        require(msg.sender == address(oracleContract), "Only oracle contract can fulfill this");
        
        // Store the received random number
        receivedRandomNumber = _randomNumber;
        randomNumberReceived = true;

        // Emit event for logging purposes
        emit RandomNumberLogged(_randomNumber);
    }

    // Check if the random number has been received
    function isRandomNumberFulfilled() public view returns (bool) {
        return randomNumberReceived;
    }

    // Return the received random number
    function getRandomNumber() public view returns (uint256) {
        require(randomNumberReceived, "Random number not yet fulfilled");
        return receivedRandomNumber;
    }
}

contracts/V2TestOracleRandomNumber.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./OracleRandomNumber.sol";

contract TestOracleRandomNumberV2 {
    OracleRandomNumber public oracleContract;
    
    // Track the latest oracle request ID for the current user
    mapping(address => uint256) public userLatestRequestId;
    
    // Map oracle request IDs to random numbers
    mapping(uint256 => uint256) public oracleIdToRandomNumber;
    
    // Map oracle request IDs to fulfillment status
    mapping(uint256 => bool) public requestFulfillmentStatus;

    // Event for logging the random number received with request ID
    event RandomNumberLogged(uint256 oracleRequestId, uint256 randomNumber);
    event RandomNumberRequested(address indexed user, uint256 oracleRequestId);

    constructor(address _oracleContractAddress) {
        // Set the address of the deployed OracleRandomNumber contract
        oracleContract = OracleRandomNumber(_oracleContractAddress);
    }

    // Function to request a random number from the OracleRandomNumber contract
    function requestRandomNumber() public returns (uint256) {
        // Get a new request ID directly from the oracle
        uint256 oracleRequestId = oracleContract.requestRandomNumber();
        
        // Map this request ID to the user
        userLatestRequestId[msg.sender] = oracleRequestId;
        
        emit RandomNumberRequested(msg.sender, oracleRequestId);
        
        return oracleRequestId;
    }

    // This function should be called by the oracle after fulfilling the random number
    function fulfillRandomNumber(uint256 _randomNumber) public {
        // Only allow the oracle contract to fulfill the random number
        require(msg.sender == address(oracleContract), "Only oracle contract can fulfill this");
        
        // Find the request ID - we need to look it up in the oracle contract
        // This is a workaround since the oracle doesn't pass the request ID to us
        uint256 latestRequestId = oracleContract.nextRequestId() - 1;
        
        // Store the received random number
        oracleIdToRandomNumber[latestRequestId] = _randomNumber;
        requestFulfillmentStatus[latestRequestId] = true;

        // Emit event for logging purposes
        emit RandomNumberLogged(latestRequestId, _randomNumber);
    }

    // Check if a user's latest random number request has been fulfilled
    function isRandomNumberFulfilled(address user) public view returns (bool) {
        uint256 requestId = userLatestRequestId[user];
        if (requestId == 0) return false; // No requests yet
        return requestFulfillmentStatus[requestId];
    }
    
    // Simplified version for current caller
    function isRandomNumberFulfilled() public view returns (bool) {
        return isRandomNumberFulfilled(msg.sender);
    }

    // Get the random number for a specific request ID
    function getRandomNumberByOracleId(uint256 oracleRequestId) public view returns (uint256) {
        require(requestFulfillmentStatus[oracleRequestId], "This request is not fulfilled yet");
        return oracleIdToRandomNumber[oracleRequestId];
    }
    
    // Get the current user's latest random number
    function getRandomNumber() public view returns (uint256) {
        uint256 requestId = userLatestRequestId[msg.sender];
        require(requestId > 0, "No random number requested yet");
        require(requestFulfillmentStatus[requestId], "Random number not yet fulfilled");
        return oracleIdToRandomNumber[requestId];
    }

    // Get the oracle request ID for a user's latest request
    function getUserLatestRequestId(address user) public view returns (uint256) {
        return userLatestRequestId[user];
    }

    // Get the current user's latest oracle request ID
    function getLatestRequestId() public view returns (uint256) {
        return userLatestRequestId[msg.sender];
    }
}

